	traverser(D, tmp, C).template for_dims<'i'>([=](auto inner) {
		// Scale D[i][l] by beta for all l at fixed i
		inner.template for_each<'l'>([=](auto state) {
			D[state] *= beta;
		});

		// Accumulate tmp * C into D over j and l
		inner.for_each([=](auto state) {
			D[state] += tmp[state] * C[state];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem sizes
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;

	// Scalars
	num_t alpha;
	num_t beta;

	// Set lengths for all logical dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl);

	// Allocate bags with the desired layouts
	auto tmp = noarr::bag(noarr::scalar<num_t>() ^ tuning.tmp_layout ^ set_lengths); // ni x nj
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout   ^ set_lengths); // ni x nk
	auto B   = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout   ^ set_lengths); // nk x nj
	auto C   = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout   ^ set_lengths); // nj x nl
	auto D   = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout   ^ set_lengths); // ni x nl

	// Initialize arrays
	init_array(alpha, beta, A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	// Time the kernel
	auto start = std::chrono::high_resolution_clock::now();

	kernel_2mm(alpha, beta, tmp.get_ref(), A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Optionally print the result matrix D to stderr
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, D.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print elapsed time in seconds to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "2mm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto l_vec = noarr::vector<'l'>();

// Layout tuning:
//   tmp: i x j
//   A  : i x k
//   B  : k x j
//   C  : j x l
//   D  : i x l
struct tuning {
	DEFINE_PROTO_STRUCT(tmp_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(a_layout,  k_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout,  j_vec ^ k_vec);
	DEFINE_PROTO_STRUCT(c_layout,  l_vec ^ j_vec);
	DEFINE_PROTO_STRUCT(d_layout,  l_vec ^ i_vec);
} tuning;

// Array initialization
// A: i x k
// B: k x j
// C: j x l
// D: i x l
void init_array(num_t &alpha, num_t &beta, auto A, auto B, auto C, auto D) {
	using namespace noarr;

	std::size_t ni = A | get_length<'i'>();
	std::size_t nj = B | get_length<'j'>();
	std::size_t nk = B | get_length<'k'>();
	std::size_t nl = C | get_length<'l'>();

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// A[i][k] = (i*k+1) % ni / ni;
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % ni) / (num_t)ni;
	});

	// B[k][j] = k*(j+1) % nj / nj;
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)(k * (j + 1) % nj) / (num_t)nj;
	});

	// C[j][l] = (j*(l+3)+1) % nl / nl;
	traverser(C).for_each([=](auto state) {
		auto [j, l] = get_indices<'j', 'l'>(state);
		C[state] = (num_t)((j * (l + 3) + 1) % nl) / (num_t)nl;
	});

	// D[i][l] = i*(l+2) % nk / nk;  (note: uses nk as in the original C code)
	traverser(D).for_each([=](auto state) {
		auto [i, l] = get_indices<'i', 'l'>(state);
		D[state] = (num_t)(i * (l + 2) % nk) / (num_t)nk;
	});
}

// Main computational kernel
// D := alpha * A * B * C + beta * D
// tmp := A * B
[[gnu::flatten, gnu::noinline]]
void kernel_2mm(num_t alpha, num_t beta, auto tmp, auto A, auto B, auto C, auto D) {
	using namespace noarr;

#pragma scop
	// First phase: tmp[i][j] = alpha * sum_k A[i][k] * B[k][j]
	traverser(tmp, A, B).template for_dims<'i'>([=](auto trav_i) {
		// i fixed here
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			// i and j fixed here, k remains
			tmp[trav_ij] = (num_t)0;

			trav_ij.for_each([=](auto state) {
				// state has i, j, k
				tmp[state] += alpha * A[state] * B[state];
			});
		});
	});

	// Second phase: D[i][l] = beta*D[i][l] + sum_j tmp[i][j] * C[j][l]
	traverser(D, tmp, C).template for_dims<'i'>([=](auto trav_i) {
		// i fixed
		trav_i.template for_dims<'l'>([=](auto trav_il) {
			// i and l fixed, j remains
			D[trav_il] *= beta;

			trav_il.for_each([=](auto state) {
				// state has i, l, j
				D[state] += tmp[state] * C[state];
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem sizes
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;

	// Scalars
	num_t alpha;
	num_t beta;

	// Shared length specification for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl);

	// Data containers (bags)
	auto tmp = noarr::bag(noarr::scalar<num_t>() ^ tuning.tmp_layout ^ set_lengths); // i x j
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout   ^ set_lengths); // i x k
	auto B   = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout   ^ set_lengths); // k x j
	auto C   = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout   ^ set_lengths); // j x l
	auto D   = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout   ^ set_lengths); // i x l

	// Initialize arrays
	init_array(alpha, beta, A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_2mm(alpha, beta, tmp.get_ref(), A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// Hoist 'i' to be the outer-most dimension for printing
		noarr::serialize_data(std::cerr, D.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
